import time
time.sleep(2)
from qgis.PyQt.QtWidgets import QAction
mw = iface.mainWindow()
a = None
for x in mw.findChildren(QAction):
    if x.objectName() == 'mConnectAction':
        a = x
        break
reg = QgsApplication.gpsConnectionRegistry()
conns = []
try:
    for c in reg.connections().values():
        conns.append({'type': type(c).__name__, 'status': str(c.status())})
except Exception as e:
    conns = 'err ' + str(e)
# sibling actions state (Recenter etc. should enable on connect)
sibs = {}
for x in mw.findChildren(QAction):
    if x.objectName() in ('mRecenterAction','mAddTrackVertexAction'):
        sibs[x.objectName()] = x.isEnabled()
result = {'connect_checked': a.isChecked(), 'connect_enabled': a.isEnabled(), 'connections': conns, 'siblings_enabled': sibs}
"}

